        if a.id != 10000 {
            return Err(super::typed::wrong_type(a, 10000));
        }
        let w = Params::new(a);
        let which = w.layout(
            match game {
                Game::Sekiro => 0,
                Game::EldenRing => 1,
            },
            &[[21, 7, 167, 39], [21, 7, 168, 40], [21, 7, 161, 30]],
        )?;
