    /// The parameters the fxr project types as enums with their stored value (`None` for a property that is not a
    /// constant): the parameter, the enum and the value.
    pub fn enum_values(&self) -> Vec<(&'static str, &'static str, Option<i32>)> {
        vec![("orientation", "RichModelOrientationMode", Some(self.orientation))]
    }

    /// The files this action refers to by number: the parameters the fxr project marks as texture, model, animation
    /// or sound references, with their value (`None` for a property that is not a constant).
    pub fn resources(&self) -> Vec<ResourceRef> {
        vec![
            ResourceRef {
                kind: ResourceKind::Model,
                param: "model",
                id: self.model.as_integer(),
            },
            ResourceRef {
                kind: ResourceKind::Animation,
                param: "anibnd",
                id: Some(self.anibnd),
            },
        ]
    }

